import{_ as e,c as r,o as t,a4 as n}from"./chunks/framework.BU14wsQo.js";const o="/ai/daily/2026-08-03/news_01kz2rmgpnenebmgdb9t1d3bt7.mp4",s="/ai/daily/2026-08-03/news_01kz2rgqwmenebmgc4rhn2dwtv.avif",l="/ai/daily/2026-08-03/news_01kz2rh0gcenebmgce8yz1jpk3.avif",i="/ai/daily/2026-08-03/news_01kz2rj14penebmgd55r1fh997.avif",h="/ai/daily/2026-08-03/news_01kz2rh7b4enebmgcn2rnfv87w.avif",f=JSON.parse('{"title":"AI大事件 2026/8/3","description":"2026-08-03 AI大事件：Inkling、OpenAI Presence、谷歌 TPU 8、TaoMate、Stream3D、Cloudflare Agents Week、MindMemOS、AirLLM 与 Grok 视频分析","frontmatter":{"linkTitle":"08-03 AI大事件","title":"AI大事件 2026/8/3","weight":29,"breadcrumbs":false,"comments":true,"description":"2026-08-03 AI大事件：Inkling、OpenAI Presence、谷歌 TPU 8、TaoMate、Stream3D、Cloudflare Agents Week、MindMemOS、AirLLM 与 Grok 视频分析"},"headers":[],"relativePath":"ai/daily/cn/2026-08/2026-08-03.md","filePath":"AI/daily/cn/2026-08/2026-08-03.md","lastUpdated":1785730243000}'),p={name:"ai/daily/cn/2026-08/2026-08-03.md"};function d(c,a,k,g,m,b){return t(),r("div",null,[...a[0]||(a[0]=[n(`<h1 align="center">2026-08-03 AI大事件</h1><h2 id="今日摘要" tabindex="-1"><strong>今日摘要</strong> <a class="header-anchor" href="#今日摘要" aria-label="Permalink to &quot;**今日摘要**&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Thinking Machines 开放 Inkling 多模态权重，OpenAI Presence 把企业智能体推进托管部署 🚀</span></span>
<span class="line"><span>谷歌 TPU 8t/8i、英伟达 Molt 与 Grok 视频分析继续刷新算力、训练和多模态产品边界 ☁️</span></span>
<span class="line"><span>TaoMate、Stream3D、模型意识表述与视觉因果基准集中抬高前沿研究密度 🧠</span></span>
<span class="line"><span>Cloudflare Agents Week 与 Jeff Dean 访谈把智能体基础设施、上下文工程推到商业前台 ( •̀ ω •́ )</span></span>
<span class="line"><span>MindMemOS、AirLLM、k-skill 与 ds4 说明开源热度继续偏向记忆、本地推理和多端部署 🛠️</span></span>
<span class="line"><span>LMChat、DeepSeek 价格战与 Astra 争议提醒我们，发布节奏、成本曲线和评测叙事都在重塑行业判断 (๑•̀ㅂ•́)و✧</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="模型与产品更新" tabindex="-1">模型与产品更新 <a class="header-anchor" href="#模型与产品更新" aria-label="Permalink to &quot;模型与产品更新&quot;">​</a></h2><h3 id="_1-inkling-开放多模态权重" tabindex="-1">1. Inkling 开放多模态权重 <a class="header-anchor" href="#_1-inkling-开放多模态权重" aria-label="Permalink to &quot;1. Inkling 开放多模态权重&quot;">​</a></h3><p><strong>Thinking Machines</strong> 发布 <strong>Inkling</strong> 多模态模型，并披露 2760 亿总参数、仅激活 120 亿参数的小版本权重。模型原生处理文字、图像与音频，NVFP4 量化后可在单张 B300 上运行；这让开放权重多模态模型从“能看图”继续走向更接近统一输入接口的形态 🚀。来源：<a href="https://thinkingmachines.ai/news/inkling-small/" target="_blank" rel="noreferrer">官方模型技术发布详情</a></p><h3 id="_2-openai-presence-推进企业智能体" tabindex="-1">2. OpenAI Presence 推进企业智能体 <a class="header-anchor" href="#_2-openai-presence-推进企业智能体" aria-label="Permalink to &quot;2. OpenAI Presence 推进企业智能体&quot;">​</a></h3><p><strong>OpenAI Presence</strong> 面向高规模、高风险工作流，提供托管式企业智能体部署，重点覆盖客服、语音和内部流程。它不是自助式产品，而是由 OpenAI 或部署伙伴配合完成系统接入、权限、评测、灰度和监控；这说明企业智能体的竞争点正从单个模型能力转向上线后的治理和持续改进 ( •̀ ω •́ )。来源：<a href="https://help.openai.com/en/articles/20001405" target="_blank" rel="noreferrer">OpenAI Presence 说明</a>、<a href="https://the-decoder.com/openai-presence-wants-to-make-ai-agents-production-ready-for-businesses/" target="_blank" rel="noreferrer">企业智能体报道</a></p><h3 id="_3-英伟达开源-molt-框架" tabindex="-1">3. 英伟达开源 Molt 框架 <a class="header-anchor" href="#_3-英伟达开源-molt-框架" aria-label="Permalink to &quot;3. 英伟达开源 Molt 框架&quot;">​</a></h3><p><strong>Molt</strong> 是英伟达发布的 PyTorch 原生智能体强化学习框架，核心代码约 8.6K 行，并组合 Ray 与 vLLM 支撑训练。它的价值在于把普通 Python 代理直接接入强化学习流程，研究者可在 H100 上复现实验，降低“智能体训练框架”从论文到工程的门槛 🛠️。来源：<a href="https://www.marktechpost.com/2026/08/01/nvidia-ai-releases-molt-a-pytorch-native-agentic-reinforcement-learning-framework/" target="_blank" rel="noreferrer">Molt 发布报道</a></p><h3 id="_4-谷歌发布八代-tpu-双芯" tabindex="-1">4. 谷歌发布八代 TPU 双芯 <a class="header-anchor" href="#_4-谷歌发布八代-tpu-双芯" aria-label="Permalink to &quot;4. 谷歌发布八代 TPU 双芯&quot;">​</a></h3><p>谷歌云公开 <strong>TPU 8t</strong> 与 <strong>TPU 8i</strong> 技术细节：前者面向大模型训练，集群规模可达 9600 芯片与 2PB 内存；后者主攻低延迟推理，并强调 80% 性价比提升。训练与推理芯片分化越来越清晰，Agent 服务的成本结构也会跟着重算 ☁️。来源：<a href="https://cloud.google.com/blog/products/compute/tpu-8t-and-tpu-8i-technical-deep-dive" target="_blank" rel="noreferrer">谷歌云官方解读</a></p><p><video src="`+o+'" controls></video></p><h3 id="_5-grok-支持分析任意视频" tabindex="-1">5. Grok 支持分析任意视频 <a class="header-anchor" href="#_5-grok-支持分析任意视频" aria-label="Permalink to &quot;5. Grok 支持分析任意视频&quot;">​</a></h3><p><strong>Grok</strong> 新增视频理解演示，用户可把动态视频交给模型分析并继续追问。这个能力把多模态交互从图文扩展到动态内容，适合快速理解素材、提取动作线索或复盘片段；但长视频、复杂剪辑和边界场景仍需要更多真实测试 ✨。来源：<a href="https://x.com/elonmusk/status/2083800942927839307" target="_blank" rel="noreferrer">Elon Musk 发布原文</a></p><h2 id="前沿研究" tabindex="-1">前沿研究 <a class="header-anchor" href="#前沿研究" aria-label="Permalink to &quot;前沿研究&quot;">​</a></h2><h3 id="_1-taomate-稳定分钟级数字人" tabindex="-1">1. TaoMate 稳定分钟级数字人 <a class="header-anchor" href="#_1-taomate-稳定分钟级数字人" aria-label="Permalink to &quot;1. TaoMate 稳定分钟级数字人&quot;">​</a></h3><p>阿里与南京大学提出 <strong>TaoMate</strong>，用 221 亿参数支撑流式音视频数字人生成。框架通过锚点记忆压制长视频中的身份和画面漂移，三卡推理可达 35 帧；如果后续开放足够稳定的工程实现，直播数字人和长时虚拟主播会更接近可用 🧠。来源：<a href="https://arxiv.org/abs/2607.24359" target="_blank" rel="noreferrer">数字人生成论文</a></p><h3 id="_2-stream3d-补全流式三维" tabindex="-1">2. Stream3D 补全流式三维 <a class="header-anchor" href="#_2-stream3d-补全流式三维" aria-label="Permalink to &quot;2. Stream3D 补全流式三维&quot;">​</a></h3><p><strong>Stream3D</strong> 面向连续视角三维补全，从视频流中逐步提取空间证据，并用固定容量记忆维持场景状态。论文给出的 GSO 测试 CD 降至 0.048，说明实时三维理解不一定要反复重训模型；更像是在给机器人和空间应用补一套可滚动更新的世界记忆 ( •̀ ω •́ )。来源：<a href="https://arxiv.org/abs/2605.21472" target="_blank" rel="noreferrer">流式三维研究论文</a></p><p><img src="'+s+'" alt="AI资讯：Stream3D对多视角场景进行三维重建补全" loading="lazy"></p><h3 id="_3-谷歌研究模型意识表述" tabindex="-1">3. 谷歌研究模型意识表述 <a class="header-anchor" href="#_3-谷歌研究模型意识表述" aria-label="Permalink to &quot;3. 谷歌研究模型意识表述&quot;">​</a></h3><p>谷歌研究团队用激活干预分析模型的心智自认、价值和情绪回答，移除拒答向量后相关得分升至 4.77。这里的重点不是证明模型“有意识”，而是说明模型对自我、价值和情绪类问题的输出可以被内部表征显著调节，评测设计会影响公众对模型能力的判断 🧪。来源：<a href="https://arxiv.org/abs/2607.28607" target="_blank" rel="noreferrer">模型意识研究论文</a></p><h3 id="_4-causalvlbench-测试视觉因果" tabindex="-1">4. CausalVLBench 测试视觉因果 <a class="header-anchor" href="#_4-causalvlbench-测试视觉因果" aria-label="Permalink to &quot;4. CausalVLBench 测试视觉因果&quot;">​</a></h3><p><strong>CausalVLBench</strong> 为多模态模型加入因果干预与反事实任务，覆盖视觉场景中的“如果改变一个条件会怎样”。现有多模态模型在这类任务上仍明显吃力，配套代码虽然只有 ⭐4，但可复现实验比单纯展示 demo 更重要；视觉理解正在从识别物体走向推理关系 🧩。来源：<a href="https://arxiv.org/html/2506.11034v2" target="_blank" rel="noreferrer">视觉因果评测论文</a></p><h2 id="行业、政策与安全" tabindex="-1">行业、政策与安全 <a class="header-anchor" href="#行业、政策与安全" aria-label="Permalink to &quot;行业、政策与安全&quot;">​</a></h2><h3 id="_1-jeff-dean-研判智能体方向" tabindex="-1">1. Jeff Dean 研判智能体方向 <a class="header-anchor" href="#_1-jeff-dean-研判智能体方向" aria-label="Permalink to &quot;1. Jeff Dean 研判智能体方向&quot;">​</a></h3><p>Jeff Dean 在访谈中判断，智能体仍会经历长期试错，算力瓶颈、上下文工程和产品品味会成为创业者真正绕不开的问题。他把 TPU 经验带回模型创业讨论：先找清楚模型盲区和系统约束，再决定产品形态，这比单纯追逐“更会写代码”的演示更稳 (๑•̀ㅂ•́)و✧。来源：<a href="https://www.ycrootaccess.com/p/jeff-dean-the-1-rule-for-building" target="_blank" rel="noreferrer">模型创业趋势访谈</a></p><p><img src="'+l+'" alt="AI资讯：Jeff Dean在访谈现场分析智能体发展方向" loading="lazy"></p><h3 id="_2-cloudflare-开启-agents-week" tabindex="-1">2. Cloudflare 开启 Agents Week <a class="header-anchor" href="#_2-cloudflare-开启-agents-week" aria-label="Permalink to &quot;2. Cloudflare 开启 Agents Week&quot;">​</a></h3><p><strong>Cloudflare</strong> 启动 Agents Week，核心问题是“Agent Cloud”应该长什么样。它认为现有云和网络主要为人类浏览器设计，而智能体需要更快的执行层、清晰的访问边界、安全控制和代理间网络；这类基础设施会决定智能体能否从单应用插件变成可运营系统 ☁️。来源：<a href="https://blog.cloudflare.com/agents-week-welcome" target="_blank" rel="noreferrer">Cloudflare 官方说明</a></p><h3 id="_3-deepseek-价格战继续升温" tabindex="-1">3. DeepSeek 价格战继续升温 <a class="header-anchor" href="#_3-deepseek-价格战继续升温" aria-label="Permalink to &quot;3. DeepSeek 价格战继续升温&quot;">​</a></h3><p>围绕 <strong>DeepSeek V4 Flash</strong> 的讨论继续发酵，低价模型让“AI 能力接近商品化”的判断更有现实压力。Axios 将其描述为模型价格战继续加速，AIHOT 聚合也显示 DeepSeek 官方 API、开源许可和多家信源集中跟进；对开发者来说，下一步可能不是只选最强模型，而是建立按任务路由的成本策略 📉。来源：<a href="https://www.axios.com/2026/08/01/deepseek-model-cheap-ai-price-war" target="_blank" rel="noreferrer">DeepSeek 价格战报道</a>、<a href="https://aihot.virxact.com/" target="_blank" rel="noreferrer">DeepSeek API 更新索引</a></p><h2 id="开源与开发者工具" tabindex="-1">开源与开发者工具 <a class="header-anchor" href="#开源与开发者工具" aria-label="Permalink to &quot;开源与开发者工具&quot;">​</a></h2><h3 id="_1-mindmemos-让记忆持续进化" tabindex="-1">1. MindMemOS 让记忆持续进化 <a class="header-anchor" href="#_1-mindmemos-让记忆持续进化" aria-label="Permalink to &quot;1. MindMemOS 让记忆持续进化&quot;">​</a></h3><p>华为诺亚开源 <strong>MindMemOS</strong>，把记忆从单个智能体中解耦出来，用三维结构保存状态与演化轨迹。它在双榜成绩达到 94.03 与 70.63%，适合观察“长期记忆层”如何从聊天记录整理走向可迁移的智能体基础设施 🧠。来源：<a href="https://github.com/mindscale-noah/MindMemOS" target="_blank" rel="noreferrer">智能体记忆开源仓库</a></p><h3 id="_2-airllm-突破显存限制-🌟25-6k" tabindex="-1">2. AirLLM 突破显存限制 🌟25.6k <a class="header-anchor" href="#_2-airllm-突破显存限制-🌟25-6k" aria-label="Permalink to &quot;2. AirLLM 突破显存限制 🌟25.6k&quot;">​</a></h3><p><strong>AirLLM</strong> 聚焦低显存大模型推理，支持 700 亿模型在 4GB 显卡上运行，仓库累计约 25.6k 星标，单日新增 819 颗星。它解决的是很朴素的问题：不用昂贵云卡，也能把大模型部署到个人或小团队环境里试起来 🛠️。来源：<a href="https://github.com/lyogavin/airllm" target="_blank" rel="noreferrer">轻显存推理项目主页</a></p><h3 id="_3-k-skill-深耕韩国本地语境-🌟6-9k" tabindex="-1">3. k-skill 深耕韩国本地语境 🌟6.9k <a class="header-anchor" href="#_3-k-skill-深耕韩国本地语境-🌟6-9k" aria-label="Permalink to &quot;3. k-skill 深耕韩国本地语境 🌟6.9k&quot;">​</a></h3><p><strong>k-skill</strong> 为智能体补齐韩国本地任务能力，仓库收录本地语境、服务流程和实用工具，累计约 6.9k 星标，单日新增 177 颗星。它提醒开发者，智能体生态不只拼通用模型能力，本地语言、平台习惯和工作流细节同样能形成壁垒 🌏。来源：<a href="https://github.com/NomaDamas/k-skill" target="_blank" rel="noreferrer">韩国智能体技能仓库</a></p><h3 id="_4-ds4-支持多端本地推理-🌟19-9k" tabindex="-1">4. ds4 支持多端本地推理 🌟19.9k <a class="header-anchor" href="#_4-ds4-支持多端本地推理-🌟19-9k" aria-label="Permalink to &quot;4. ds4 支持多端本地推理 🌟19.9k&quot;">​</a></h3><p><strong>ds4</strong> 让 DeepSeek4 登陆本地设备，兼容 Metal 与多类显卡后端，仓库累计约 19.9k 星标，单日新增 139 颗星。多硬件后端的意义在于减少云端依赖，让不同设备都能参与推理实验，尤其适合预算敏感的个人开发者和小团队 (^_^)v。来源：<a href="https://github.com/antirez/ds4" target="_blank" rel="noreferrer">多端推理开源仓库</a></p><h2 id="社媒与观点" tabindex="-1">社媒与观点 <a class="header-anchor" href="#社媒与观点" aria-label="Permalink to &quot;社媒与观点&quot;">​</a></h2><h3 id="_1-kimi-k3-开源模型深读" tabindex="-1">1. Kimi K3 开源模型深读 <a class="header-anchor" href="#_1-kimi-k3-开源模型深读" aria-label="Permalink to &quot;1. Kimi K3 开源模型深读&quot;">​</a></h3><p>一篇技术深读把 <strong>Kimi K3</strong> 放在开放模型竞争中拆解，重点关注 2.78 万亿参数、KDA 长上下文能力与稳定 MoE 训练。它更像是一篇研究笔记而非发布新闻，价值在于帮读者看清模型规模、路由结构和工程权衡如何共同影响开源模型上限 🧭。来源：<a href="https://imrancoder786.github.io/blog-post.html?post=kimi-k3-deep-dive" target="_blank" rel="noreferrer">技术深读全文</a></p><h3 id="_2-agi-bar-免费-token-上线" tabindex="-1">2. AGI Bar 免费 token 上线 <a class="header-anchor" href="#_2-agi-bar-免费-token-上线" aria-label="Permalink to &quot;2. AGI Bar 免费 token 上线&quot;">​</a></h3><p>北京 <strong>AGI Bar</strong> 开始提供店内免费 token 服务，用户进店连 WiFi 即可调用，先供应 DeepSeek V4 Flash，并称后续上海店也会接入。这个案例有点像把本地推理变成线下体验入口：技术不再只在云端控制台里，也可以成为门店获客和社区运营的一部分 🔌。来源：<a href="https://m.okjike.com/originalPosts/6a6f4583cfb5d08b3eb59c10" target="_blank" rel="noreferrer">即刻发布原文</a></p><p><img src="'+i+'" alt="AI资讯：AGI Bar店内免费token服务海报" loading="lazy"></p><h3 id="_3-谷歌错过-lmchat-窗口" tabindex="-1">3. 谷歌错过 LMChat 窗口 <a class="header-anchor" href="#_3-谷歌错过-lmchat-窗口" aria-label="Permalink to &quot;3. 谷歌错过 LMChat 窗口&quot;">​</a></h3><p>围绕 <strong>LMChat</strong> 的讨论再次升温：OpenAI 产品负责人 Tibo Sottiaux 称自己曾参与 Google 内部聊天机器人项目，时间大约早于 ChatGPT 一年，但产品没有对外发布。独立报道也将其放到 LaMDA、Meena 和搜索业务包袱的背景下解读；这条更适合作为发布节奏与组织风险的案例，而不是简单归因成技术输赢 ┐(´-｀)┌。来源：<a href="https://x.com/thsottiaux/status/2083596911060324570" target="_blank" rel="noreferrer">Tibo 原帖</a>、<a href="https://www.blocktempo.com/openai-product-lead-sottiaux-google-lmchat-chatgpt-year-earlier-deepmind/" target="_blank" rel="noreferrer">LMChat 独立报道</a></p><p><img src="'+h+'" alt="AI资讯：谷歌LMChat讨论截图与推文证言" loading="lazy"></p><h3 id="_4-astra-数学表现引发质疑" tabindex="-1">4. Astra 数学表现引发质疑 <a class="header-anchor" href="#_4-astra-数学表现引发质疑" aria-label="Permalink to &quot;4. Astra 数学表现引发质疑&quot;">​</a></h3><p>Gary Marcus 对 OpenAI 内部测试模型 <strong>Astra</strong> 的数学表现提出质疑，认为“擅长某类数学题”不能自动外推为擅长所有数学、科学或认知任务。数学任务适合符号验证，也更容易生成大量合成数据；在方法细节未公开前，这类跑分叙事需要保持克制 🧮。来源：<a href="https://garymarcus.substack.com/p/openais-amazing-but-vastly-oversold" target="_blank" rel="noreferrer">Gary Marcus 评论</a></p><h3 id="_5-开源模型盘点聚焦-inkling-与-kimi-k3" tabindex="-1">5. 开源模型盘点聚焦 Inkling 与 Kimi K3 <a class="header-anchor" href="#_5-开源模型盘点聚焦-inkling-与-kimi-k3" aria-label="Permalink to &quot;5. 开源模型盘点聚焦 Inkling 与 Kimi K3&quot;">​</a></h3><p>Nathan Lambert 的开放模型盘点把 Laguna S2.1、Inkling 与 Kimi K3 放在同一张“开放 artifact”图谱里。它补充了今天 Inkling 发布之外的观察：开放模型的竞争不只看单次发布，还要看权重、推理成本、社区复现和后续迭代能否形成帕累托前沿 ( •̀ ω •́ )。来源：<a href="https://www.interconnects.ai/p/latest-open-artifacts-23-laguna-s21" target="_blank" rel="noreferrer">开放模型盘点</a></p><h2 id="今日总结与启示" tabindex="-1">今日总结与启示 <a class="header-anchor" href="#今日总结与启示" aria-label="Permalink to &quot;今日总结与启示&quot;">​</a></h2><ul><li><strong>企业智能体进入治理阶段。</strong> Presence 和 Cloudflare Agents Week 都在强调权限、评测、监控与基础设施，说明智能体落地已经绕不开生产工程 🚀。</li><li><strong>多模态和算力继续分层。</strong> Inkling、Grok 视频分析、TPU 8t/8i 共同指向一个趋势：输入更统一，底层硬件却更专业化 ☁️。</li><li><strong>研究开始补齐长程一致性。</strong> TaoMate 的锚点记忆、Stream3D 的固定容量记忆和视觉因果基准都在处理“连续世界”问题 🧠。</li><li><strong>开源项目更偏实用基础件。</strong> MindMemOS、AirLLM、k-skill、ds4 都不是纯展示项目，而是在帮开发者解决记忆、本地化、显存和设备适配 🛠️。</li><li><strong>行业叙事要看证据强度。</strong> LMChat、Astra 和 DeepSeek 价格战都很热，但真正值得跟进的是可核验来源、成本曲线和可复现指标 (๑•̀ㅂ•́)و✧。</li></ul>',57)])])}const _=e(p,[["render",d]]);export{f as __pageData,_ as default};
